#define main coin_bump_completion_offscreen_main
#include "CoinRenderBumpCompletionTest.cpp"
#undef main
#include <Inventor/rendering/CoinRenderNativeSurface.h>
#include <X11/Xlib.h>
#include <X11/Xutil.h>
#ifdef Status
#undef Status
#endif
#include <chrono>
namespace {
unsigned channel(unsigned long value,unsigned long mask){if(!mask)return 0;while(!(mask&1)){value>>=1;mask>>=1;}return unsigned((value&mask)*255/mask);}
bool shown(Display*d,Window w,unsigned n,Frame&f){XSync(d,False);XWindowAttributes a{};if(!XGetWindowAttributes(d,w,&a)||a.width!=int(n)||a.height!=int(n))return false;auto*image=XGetImage(d,w,0,0,n,n,AllPlanes,ZPixmap);if(!image)return false;f.rgba.resize(size_t(n)*n*4);for(unsigned y=0;y<n;++y)for(unsigned x=0;x<n;++x){auto pixel=XGetPixel(image,x,y);auto i=(size_t(y)*n+x)*4;f.rgba[i]=channel(pixel,image->red_mask);f.rgba[i+1]=channel(pixel,image->green_mask);f.rgba[i+2]=channel(pixel,image->blue_mask);f.rgba[i+3]=255;}XDestroyImage(image);return true;}
bool window(unsigned samples,bool srgb,bool readback,unsigned family){Display*d=XOpenDisplay(nullptr);if(!d)return false;unsigned n=side;Window w=XCreateSimpleWindow(d,DefaultRootWindow(d),10,10,n,n,0,0,0);XSetWindowAttributes attr{};attr.override_redirect=True;XChangeWindowAttributes(d,w,CWOverrideRedirect,&attr);XMapRaised(d,w);XSync(d,False);CoinRenderNativeSurfaceDescriptor native{};native.abiVersion=COIN_RENDER_NATIVE_SURFACE_ABI_VERSION;native.structSize=sizeof(native);native.type=COIN_RENDER_SURFACE_XLIB;native.native.xlib.display=d;native.native.xlib.window=w;auto options=samplingTestOptions();options.sampleCount=samples;if(srgb)options.storedTextureColorSpace=COIN_RENDER_TEXTURE_SRGB;std::unique_ptr<CoinRenderTarget>target(CoinRenderTarget::createWindow(native,SbVec2i32(n,n),options));bool ok=check(bool(target),"real window factory");if(target){auto&p=target->getPimpl().get();ok &=check(p.prepareBackend()==CoinRenderBackendStatus::SUCCESS&&p.backend&&p.backend->isGpuBackend(),"actual GPU window backend");if(ok){Spatial scene(8,true,family,7);CoinRenderAction action(SbViewportRegion(n,n));action.setRenderTarget(target.get());action.setTransparencyType(CoinRenderAction::NONE);action.setBackgroundColor(SbColor4f(0,0,0,1));
  Frame stable,stableRead;auto draw=[&](Frame&physical,Frame&read,const char*phase){if(readback&&!target->requestWindowReadbackRGBA())return false;auto before=target->getLastSubmissionSerial();const auto start=std::chrono::steady_clock::now();action.apply(scene.scene.root);target->readbackRGBA(read.rgba);read.serial=target->getLastSubmissionSerial();if(!check(action.getLastStatus()==CoinRenderAction::SUCCESS&&read.serial>before,"single apply renders/presents current mixed-light window"))return false;const auto value=scene.sampled(srgb,false);bool valid=readback?oracle(scene.scene,read,[&](double,double){return value;},n,false):check(read.rgba.empty(),"physical-only window carries no CPU readback");if(readback)valid &=check(read.rgba.size()==size_t(n)*n*4,"same-apply complete window readback");
    const auto observationStart=std::chrono::steady_clock::now(),deadline=observationStart+std::chrono::seconds(5);unsigned observations=0;bool current=false,firstCurrent=false;double firstMs=0;
    do{++observations;bool matched=shown(d,w,n,physical)&&oracle(scene.scene,physical,[&](double,double){return value;},n,false,false);if(readback){matched &=physical.rgba.size()==read.rgba.size();if(physical.rgba.size()==read.rgba.size())for(size_t i=0;i<read.rgba.size();i+=4)for(unsigned c=0;c<3;++c)matched &=std::abs(int(read.rgba[i+c])-int(physical.rgba[i+c]))<=3;}const auto now=std::chrono::steady_clock::now();if(observations==1){firstCurrent=matched;firstMs=std::chrono::duration<double,std::milli>(now-start).count();}if(matched&&now<=deadline){current=true;break;}}while(std::chrono::steady_clock::now()<deadline);
    std::cout<<"completion_window phase="<<phase<<" extent="<<n<<" first_read_ms="<<firstMs<<" first_current="<<firstCurrent<<" observations="<<observations<<" ms="<<std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()<<'\n';if(!current)oracle(scene.scene,physical,[&](double,double){return value;},n,false);return valid&&check(current,"one apply becomes physically current within original five-second observation deadline, no sleeps or rendering retries");};
  ok &=draw(stable,stableRead,"A");Frame b,br,back,backRead;scene.scene.setNormal({{78,173,232}});ok &=draw(b,br,"normal B")&&check(b.rgba!=stable.rgba,"physical current normal B");scene.scene.setNormal({{153,108,241}});ok &=draw(back,backRead,"normal A")&&check(back.rgba==stable.rgba,"physical A/B/A exact");
  const auto serial=target->getLastSubmissionSerial();scene.scene.matrix->translation.setValue(std::numeric_limits<float>::quiet_NaN(),0);if(readback)ok &=target->requestWindowReadbackRGBA();action.apply(scene.scene.root);Frame rejected,physical;target->readbackRGBA(rejected.rgba);ok &=check(action.getLastStatus()!=CoinRenderAction::SUCCESS&&action.getLastError().getLength()&&target->getLastSubmissionSerial()==serial&&rejected.rgba==backRead.rgba&&shown(d,w,n,physical)&&physical.rgba==back.rgba,"window malformed current input preserves prior physical/readback/serial");scene.scene.matrix->translation.setValue(0,0);ok &=draw(back,backRead,"malformed recovery");
  for(unsigned extent:{128u,96u}){n=extent;XResizeWindow(d,w,n,n);XSync(d,False);ok &=target->resize(SbVec2i32(n,n));action.setViewportRegion(SbViewportRegion(n,n));ok &=draw(back,backRead,"resized window");}ok &=check(back.rgba==stable.rgba,"resize A/B/A restores exact current physical image");action.setRenderTarget(nullptr);
 }}target.reset();XDestroyWindow(d,w);XCloseDisplay(d);return ok;}
}
int main(int argc,char**argv){if(!check(XInitThreads()!=0,"Xlib thread support initializes before SoDB, capability query and window creation"))return 1;SoDB::init();CoinRenderAction::initClass();configureSamplingTest(argc,argv);unsigned samples=1,family=1;bool srgb=false,readback=false;for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--samples"&&i+1<argc)samples=std::atoi(argv[++i]);else if(a=="--family"&&i+1<argc)family=std::atoi(argv[++i]);else if(a=="--srgb")srgb=true;else if(a=="--readback")readback=true;}if(samples!=1&&samples!=2&&samples!=4)return 2;if(family>2)return 2;CoinRenderCapabilities caps{};if(coin_render_query_capabilities(COIN_RENDER_EXPERIMENTAL_XLIB_WINDOW,&caps,sizeof(caps)))return 1;if(!caps.gpu_available)return 77;return window(samples,srgb,readback,family)?0:1;}
